//! Env-gated parity corpora against the Python authority.
//!
//! The corpora are generated by the Python side, so they are not fixtures this
//! crate owns. Every test here is `#[ignore]`d: a plain `cargo test` reports
//! them as **ignored**, never as passed, because nothing was checked. They run
//! only when asked for explicitly, with the corpus variables set:
//!
//! ```text
//! .venv/Scripts/python.exe .tmp_adversarial540/geometry-rust/gen_float_corpus.py
//! .venv/Scripts/python.exe .tmp_adversarial540/geometry-rust/gen_number_corpus.py
//! .venv/Scripts/python.exe .tmp_adversarial540/geometry-rust/gen_geometry_corpus.py
//! BOARDWISE_540C_FLOAT_CORPUS=.tmp_adversarial540/geometry-rust/float-corpus.jsonl \
//! BOARDWISE_540C_NUMBER_CORPUS=.tmp_adversarial540/geometry-rust/number-corpus.jsonl \
//! BOARDWISE_540C_GEOMETRY_CORPUS=.tmp_adversarial540/geometry-rust/geometry-corpus.jsonl \
//!   bash .tmp_540/rust-buildtools/cargo-local.sh test -p boardwise-core \
//!     --test python_compat_corpus -- --ignored
//! ```
//!
//! `--ignored` without a variable is a hard failure (the test demands its own
//! corpus), so such a run can never look green while nothing was read.
//!
//! What a green run means: for every sampled double, `python_float_repr` spells
//! it exactly like CPython's `repr`; for every sampled JSON number literal
//! `serde_json` reads the same double Python's `json.loads` + `float()` reads
//! (and classifies it as integer or float the same way); and for every sampled
//! LayoutPlan variant the canonical geometry JSON and its digest are byte-equal
//! to Python's `LayoutPlan.geometry_json` / `geometry_sha256`.

use boardwise_core::{geometry_json, geometry_sha256, python_float_repr};
use serde_json::Value;
use std::fs;
use std::path::{Path, PathBuf};

/// A corpus path from the environment, relative ones resolved against the
/// repository root (cargo runs test binaries with the crate directory as cwd).
fn corpus_path(variable: &str) -> Option<PathBuf> {
    let value = std::env::var(variable).ok()?;
    let path = PathBuf::from(value);
    if path.is_absolute() {
        Some(path)
    } else {
        Some(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .ancestors()
                .nth(3)
                .expect("repository root")
                .join(path),
        )
    }
}

fn corpus_rows(path: &Path) -> Vec<Value> {
    let text = fs::read_to_string(path).expect("corpus is readable");
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| serde_json::from_str(line).expect("corpus row is JSON"))
        .collect()
}

#[test]
#[ignore = "requires the corresponding Python parity corpus"]
fn float_repr_matches_python_corpus() {
    let path = corpus_path("BOARDWISE_540C_FLOAT_CORPUS")
        .expect("set BOARDWISE_540C_FLOAT_CORPUS to the Python float-repr corpus");
    let rows = corpus_rows(&path);
    let mut failures = Vec::new();
    let mut mismatches = 0_usize;
    for row in &rows {
        let bits_text = row["bits"].as_str().expect("bits");
        let bits = u64::from_str_radix(bits_text, 16).expect("hex bits");
        let expected = row["repr"].as_str().expect("repr");
        let got = python_float_repr(f64::from_bits(bits));
        if got != expected {
            mismatches += 1;
            if failures.len() < 20 {
                failures.push(format!(
                    "bits {bits_text}: python {expected:?}, rust {got:?}"
                ));
            }
        }
    }
    assert!(
        mismatches == 0,
        "{mismatches} of {} sampled doubles spell differently: {failures:#?}",
        rows.len()
    );
    assert!(rows.len() > 100_000, "the corpus must be a real sample");
}

#[test]
#[ignore = "requires the corresponding Python parity corpus"]
fn json_number_literals_parse_like_python() {
    let path = corpus_path("BOARDWISE_540C_NUMBER_CORPUS")
        .expect("set BOARDWISE_540C_NUMBER_CORPUS to the Python number-literal corpus");
    let rows = corpus_rows(&path);
    let mut failures = Vec::new();
    let mut mismatches = 0_usize;
    for row in &rows {
        let literal = row["literal"].as_str().expect("literal");
        let kind = row["kind"].as_str().expect("kind");
        let bits_text = row["bits"].as_str().expect("bits");
        let expected_bits = u64::from_str_radix(bits_text, 16).expect("hex bits");
        let expected_repr = row["repr"].as_str().expect("repr");

        let parsed: Value = serde_json::from_str(literal).expect("literal is JSON");
        let number = parsed.as_f64().expect("literal is a number");
        let rust_kind = if parsed.as_number().expect("number").is_f64() {
            "float"
        } else {
            "int"
        };
        let got = python_float_repr(number);
        let mut problems = Vec::new();
        if number.to_bits() != expected_bits {
            problems.push(format!(
                "value {:016x} vs python {:016x}",
                number.to_bits(),
                expected_bits
            ));
        }
        if got != expected_repr {
            problems.push(format!("repr {got:?} vs python {expected_repr:?}"));
        }
        if rust_kind != kind {
            problems.push(format!("kind {rust_kind} vs python {kind}"));
        }
        if !problems.is_empty() {
            mismatches += 1;
            if failures.len() < 20 {
                failures.push(format!("{literal}: {}", problems.join("; ")));
            }
        }
    }
    assert!(
        mismatches == 0,
        "{mismatches} of {} literals read differently: {failures:#?}",
        rows.len()
    );
    assert!(rows.len() > 10_000, "the corpus must be a real sample");
}

#[test]
#[ignore = "requires the corresponding Python parity corpus"]
fn geometry_corpus_matches_python() {
    let path = corpus_path("BOARDWISE_540C_GEOMETRY_CORPUS")
        .expect("set BOARDWISE_540C_GEOMETRY_CORPUS to the Python geometry corpus");
    let rows = corpus_rows(&path);
    let mut failures = Vec::new();
    for row in &rows {
        let name = row["name"].as_str().expect("name");
        let expected_canonical = row["canonical"].as_str().expect("canonical");
        let expected_digest = row["digest"].as_str().expect("digest");
        let payload = &row["payload"];
        match geometry_json(payload) {
            Err(error) => failures.push(format!("{name}: Rust refused the payload ({error})")),
            Ok(canonical) => {
                if canonical != expected_canonical {
                    failures.push(format!(
                        "{name}: canonical JSON differs
  python: {expected_canonical}
  rust:   {canonical}"
                    ));
                }
            }
        }
        match geometry_sha256(payload) {
            Err(error) => failures.push(format!("{name}: no digest ({error})")),
            Ok(digest) if digest != expected_digest => failures.push(format!(
                "{name}: digest {digest} vs python {expected_digest}"
            )),
            Ok(_) => {}
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} geometry variants differ: {failures:#?}",
        failures.len(),
        rows.len()
    );
    assert!(rows.len() >= 30, "the corpus must cover the field map");
}
